when.if:
AND EXISTS (
    SELECT 1
    FROM its_application_data app
    WHERE app.cmdb_id = uar.cmdb_id
    AND app.application_name = #{request.filters.appName}
)

mapper.update:
INSERT INTO pre_send_for_user_will_remove (recipient, recipient_email) SELECT lower(uar.it_code_of_user) AS recipient, lower(u.email) AS recipient_email FROM user_access_review uar LEFT JOIN ad_tb_upp_nature_2 u ON uar.it_code_of_user = u.user_name
u.band_flag = '0' AND uar.line_manager not in( select user_name from ad_tb_upp_nature_2 where band_flag = '1' ) AND ( uar.line_managers_review_decision = 'remove' OR uar.bpo_review_decision = 'remove' ) AND uar.delete_flag = '0' AND u.email IS NOT NULL AND u.email != ''
GROUP BY lower(uar.it_code_of_user), lower(u.email);

WITH target_users AS ( SELECT DISTINCT LOWER(TRIM(uar.it_code_of_user)) AS recipient, LOWER(TRIM(ad.email)) AS recipient_email FROM user_access_review uar INNER JOIN ad_tb_upp_nature_2 ad ON LOWER(TRIM(uar.it_code_of_user)) = LOWER(TRIM(ad.user_name))
uar.final_review_decision = 'remove' AND uar.delete_flag = '0' AND ad.band_flag = '0' AND ad.email IS NOT NULL AND ad.email != ''
) INSERT INTO pre_send_for_final_remove (recipient, recipient_email) SELECT recipient, recipient_email FROM target_users
